// =====================================================================
//  Aloe regrow + Blastberry tech + Jellybean buffing   (Plot 1 script)
//  Flow: Hybridize -> Aloe -> Step 3 (shadevines), looping.
//
//  1. Aloe regrow (shadevine step): a harvested All-in Aloe spot waits
//     empty until the regrow trigger below is met (a number of waiting
//     spots, or a number of cycles since the oldest one was harvested).
//     Then the PlantBoy Advance and Magic Jellybeans that surrounded the
//     waiting spots in the Aloe step are planted back around them (only
//     what those spots need), so new aloes can spawn there. Every other
//     cell keeps the shadevine layout. Once an aloe is back, its cells
//     return to shadevines (see REMOVE_SCAFFOLD_AFTER_REGROW).
//  2. Blastberry tech (mimicked, nothing is placed): every aloe is
//     harvested with +30% yield and immunity, as if a Blastberry had been
//     put next to it just before the harvest, and 1 Magic Jellybean leaves
//     the inventory for it (the placed Jellybean you break to make room).
//     That Jellybean is spent, not harvested, so harvest conditions don't
//     count it. Aloes that already hold both effects (Cocoa Beans + Nether
//     Wart next to them) need no Blastberry and cost nothing.
//     Aloes are harvested at the stage your All-in Aloe harvest setting
//     picks; when the step is about to end, aloes the next step would clear
//     are harvested first so they get the tech too.
//  3. Jellybean buff: at the last session before a growing Magic
//     Jellybean becomes fully grown (using your time between sessions),
//     a Cocoa Beans (immunity) and a Nether Wart (+30% yield) are planted
//     next to it, so it locks those effects instead of Harvest Loss.
//     From then until the step ends no aloe is regrown and no PlantBoy
//     is planted.
// =====================================================================

// ---- Settings ----
const REGROW_ALOE = true;
// When to start rebuilding the PlantBoy/Jellybeans around harvested aloe spots.
// Leave both null to rebuild right after each harvest. With both set, the first
// one met starts the rebuild. Every waiting spot is rebuilt together.
const REGROW_AFTER_ALOES = null; // rebuild once this many harvested spots are waiting
const REGROW_INTERVAL = null;    // rebuild once the oldest waiting spot has waited this many cycles
// A waiting spot whose PlantBoy/Jellybeans are all standing already (another spot's
// rebuild put them up) starts regrowing right away: it costs nothing extra.
const JOIN_IF_SCAFFOLD_UP = true;
const REMOVE_SCAFFOLD_AFTER_REGROW = true; // false: keep the PlantBoy/Jellybeans for the next regrow
const BLASTBERRY_TECH = true;
const BUFF_JELLYBEANS = true;
// Cycles between your sessions (your harvest interval). null = learn it
// from the run (works for "every N cycles" and for time windows).
const HARVEST_INTERVAL = null;

const ALOE = "all_in_aloe";
const JB = "magic_jellybean";
const PB = "plantboy_advance";
const COCOA = "cocoa_beans";   // gives Immunity
const WART = "nether_wart";    // gives Improved Harvest Boost

// Stage the built-in "auto" All-in Aloe harvest picks, by cycles until the
// next session (row) and respawn chance per mille ("min:stage", high to low).
// Generated from the simulator's own aloeHarvestStageFor.
const AUTO_STAGE = [
  "86:14 40:15 17:16 7:17 3:18 2:19 1:20",
  "218:13 58:14 26:15 11:16 5:17 2:18 1:19",
  "112:13 38:14 17:15 8:16 4:17 2:18 1:19",
  "240:12 67:13 26:14 12:15 6:16 3:17 2:18 1:19",
  "397:11 120:12 42:13 18:14 9:15 4:16 2:17 1:18",
  "181:11 69:12 29:13 14:14 7:15 3:16 2:17 1:18",
  "464:10 104:11 47:12 21:13 10:14 5:15 3:16 2:17 1:18",
  "215:10 71:11 35:12 17:13 8:14 4:15 2:16 1:17",
  "125:10 51:11 27:12 14:13 7:14 4:15 2:16 1:17",
  "861:8 187:9 78:10 37:11 21:12 11:13 6:14 3:15 2:16 1:17",
  "635:7 283:8 111:9 56:10 28:11 17:12 10:13 5:14 3:15 2:16 1:17",
  "519:6 327:7 164:8 81:9 45:10 24:11 14:12 8:13 5:14 3:15 2:16 1:17",
  "487:5 306:6 208:7 119:8 66:9 39:10 21:11 13:12 8:13 4:14 3:15 2:16 1:17",
  "514:4 309:5 213:6 155:7 97:8 58:9 36:10 20:11 12:12 7:13 4:14 3:15 2:16 1:17",
  "341:4 227:5 166:6 127:7 85:8 53:9 33:10 19:11 12:12 7:13 4:14 2:15 1:16",
  "255:4 182:5 139:6 111:7 77:8 50:9 32:10 18:11 11:12 7:13 4:14 2:15 1:16",
  "208:4 156:5 123:6 101:7 72:8 47:9 30:10 17:11 11:12 6:13 4:14 2:15 1:16",
  "182:4 140:5 113:6 94:7 68:8 45:9 29:10 17:11 10:12 6:13 4:14 2:15 1:16",
  "167:4 131:5 107:6 89:7 64:8 42:9 28:10 16:11 10:12 6:13 3:14 2:15 1:16",
  "160:4 125:5 101:6 84:7 61:8 40:9 26:10 15:11 9:12 5:13 3:14 2:15 1:16",
  "156:4 120:5 96:6 80:7 57:8 38:9 24:10 14:11 9:12 5:13 3:14 2:15 1:16",
  "154:4 115:5 92:6 76:7 53:8 35:9 23:10 13:11 8:12 5:13 3:14 2:15 1:16",
  "150:4 111:5 87:6 71:7 50:8 33:9 22:10 13:11 8:12 5:13 3:14 2:15 1:16",
  "148:4 106:5 82:6 66:7 47:8 31:9 20:10 12:11 8:12 5:13 3:14 2:15 1:16",
];

// ---- Kept between cycles ----
let aloeSource = null;   // Aloe-step layout: { spots: ["r,c"], scaffold: { "r,c": [plants] } }
let layoutsSeen = {};    // step id -> cells where that step keeps an aloe
let leavingTo = null;    // step this session's step change goes to, or null
let base = null;         // this step's own layout
let waiting = {};        // harvested aloe spots waiting for the regrow trigger -> cycle harvested
let pending = {};        // harvested aloe spots being regrown (scaffold up)
let emptied = {};        // harvested aloe spots left empty (buff phase / regrow off)
let kept = {};           // spots whose scaffold stays (REMOVE_SCAFFOLD_AFTER_REGROW = false)
let buffCells = {};      // "r,c" -> cocoa_beans / nether_wart
let buffed = {};         // jellybean plant id -> true
let buffPhase = false;
let appliedKey = null;
let qBySpot = {};
let lastSession = null;
let lastHour = null;
let gapByHour = {};
let recentGaps = [];
let tally = { aloeHarvested: 0, aloeBuffed: 0, jellybeansSpent: 0, regrowBatches: 0, regrowStarted: 0, regrown: 0, jellybeansBuffed: 0 };
let warned = {};

// ---- Small helpers ----
const key = (r, c) => `${r},${c}`;
const cellOf = (k) => k.split(",").map((x) => Number(x));
const inside = (r, c) => r >= 0 && r < 10 && c >= 0 && c < 10;
const ORTHO = [[-1, 0], [1, 0], [0, -1], [0, 1]];

function orth(r, c) {
  return ORTHO.map(([dr, dc]) => [r + dr, c + dc]).filter(([a, b]) => inside(a, b));
}

function ring(r, c) {
  const out = [];
  for (let dr = -1; dr <= 1; dr++) for (let dc = -1; dc <= 1; dc++) {
    if ((dr || dc) && inside(r + dr, c + dc)) out.push(key(r + dr, c + dc));
  }
  return out;
}

function footprint(row, col, size) {
  const out = [];
  for (let dr = 0; dr < size; dr++) for (let dc = 0; dc < size; dc++) out.push(key(row + dr, col + dc));
  return out;
}

function warnOnce(id, text) {
  if (warned[id]) return;
  warned[id] = true;
  warn(text);
}

function targetAt(r, c) {
  const t = plot.targets.find((t) => t.row === r && t.col === c);
  return t ? t.mutation : null;
}

const isGrowingJellybean = (p) => p && p.kind === JB && p.spawned && !p.dead;
const isSpot = (k) => !!aloeSource && aloeSource.spots.includes(k);
// This step keeps aloes as layout inputs (the shadevine step): regrowing needs our help.
const regrowStep = () => !!base && !!aloeSource && base.plants.some((p) => p.kind === ALOE && isSpot(key(p.row, p.col)));

// ---- Learning the layouts ----
function capture() {
  base = plot.layout;
  // Cells where this step keeps an aloe (input or target), to know if leaving the step clears them.
  layoutsSeen[plot.step.id] = [...base.plants, ...base.targets]
    .filter((e) => (e.kind ?? e.mutation) === ALOE)
    .map((e) => key(e.row, e.col));
  const spots = base.targets.filter((t) => t.mutation === ALOE).map((t) => key(t.row, t.col));
  if (!spots.length) return;
  // This step grows aloes: remember which PlantBoys / Jellybeans surround each spot.
  const scaffold = {};
  for (const s of spots) {
    const [r, c] = cellOf(s);
    const around = ring(r, c);
    scaffold[s] = base.plants
      .filter((p) => (p.kind === JB || p.kind === PB) && footprint(p.row, p.col, p.size).some((k) => around.includes(k)))
      .map((p) => ({ kind: p.kind, row: p.row, col: p.col, size: p.size }));
  }
  aloeSource = { spots, scaffold };
}

function resetStep() {
  base = null;
  waiting = {};
  pending = {};
  emptied = {};
  kept = {};
  buffCells = {};
  buffed = {};
  buffPhase = false;
  appliedKey = null;
  qBySpot = {};
}

// ---- Time between sessions ----
function trackGap() {
  if (lastSession !== null && cycle > lastSession) {
    const g = cycle - lastSession;
    gapByHour[lastHour] = g;
    recentGaps.push(g);
    if (recentGaps.length > 48) recentGaps.shift();
  }
  lastSession = cycle;
  lastHour = String(Math.floor(hour));
}

/** Cycles until the next session, as best we know (bigger is the safe side). */
function predictGap() {
  if (HARVEST_INTERVAL) return HARVEST_INTERVAL;
  // Gaps seen after sessions at about this time of day.
  const h = Math.floor(hour);
  const near = [-2, -1, 0, 1, 2].map((d) => gapByHour[String((h + d + 24) % 24)]).filter((g) => g !== undefined);
  if (near.length) return Math.max(...near);
  return recentGaps.length ? recentGaps.max() : 1;
}

/** For the Jellybean buff, err early: with online windows sessions drift a little from day to day. */
function buffGap(gap) {
  if (HARVEST_INTERVAL) return HARVEST_INTERVAL;
  return gap + (recentGaps.some((g) => g !== recentGaps[0]) ? 1 : 0);
}

// ---- All-in Aloe harvest stage (mirrors the built-in setting) ----
function autoStage(gap, q) {
  const row = AUTO_STAGE[Math.max(1, Math.min(AUTO_STAGE.length, Math.floor(gap))) - 1].split(" ");
  const p = q > 0 ? Math.max(1, Math.min(1000, Math.round(q * 1000))) : 1000; // can't respawn: plan as instant
  for (const entry of row) {
    const [min, stage] = entry.split(":").map((x) => Number(x));
    if (p >= min) return stage;
  }
  return 14;
}

function defaultQ() {
  const w = info(ALOE).spawnWeight * (1 + (stats.mutationChanceBonus ?? 0));
  return Math.min(1, w / 100);
}

/** Respawn chance the harvest plan assumes for the aloe at this spot. */
function spotQ(k) {
  if (base && base.targets.some((t) => t.mutation === ALOE && key(t.row, t.col) === k)) return qBySpot[k] ?? defaultQ();
  if (regrowStep() && isSpot(k) && REGROW_ALOE && !buffPhase) return qBySpot[k] ?? defaultQ();
  return 0;
}

function dueStage(p, gap) {
  if (!config.aloeAutoHarvest) return Math.max(1, Math.min(27, Math.floor(config.aloeHarvestStage)));
  return autoStage(gap, spotQ(key(p.row, p.col)));
}

// ---- Blastberry tech (mimicked) ----
// Nothing is placed for it. The aloes being harvested hold the Blastberry's effects
// for that moment only (forced effects), and 1 Magic Jellybean per aloe leaves the
// inventory: it is placed on the aloe's now-empty cell and broken straight away,
// which spends it without counting as a harvest.
const BB_EFFECTS = ["immunity", "improved_harvest_boost"];

function withBlastberry(run) {
  const before = forcedEffects;
  forceEffects(ALOE, [...(before[ALOE] ?? []), ...BB_EFFECTS]);
  run();
  // Back to what was forced before (usually nothing).
  const norm = (o) => JSON.stringify(keys(o ?? {}).sort().map((k) => [k, o[k]]));
  if (norm(before) === norm(config.forcedEffects)) resetForcedEffects();
  else if (before[ALOE]) forceEffects(ALOE, before[ALOE]);
  else unforceEffects(ALOE);
}

function spendJellybean(r, c) {
  if (!plot.place(JB, r, c)) return false;
  plot.breakAt(r, c);
  tally.jellybeansSpent++;
  return true;
}

const alreadyBuffed = (a) => BB_EFFECTS.every((e) => a.hasEffect(e)); // e.g. next to Cocoa + Nether Wart

/**
 * The step ends this session and the next step doesn't keep this aloe:
 * harvest it now (if it pays) so it still gets the tech.
 */
function clearedByStepChange(p) {
  if (!leavingTo || !layoutsSeen[leavingTo]) return false;
  return p.stage >= 4 && !layoutsSeen[leavingTo].includes(key(p.row, p.col));
}

function harvestAloes(gap) {
  const due = plot.spawns(ALOE).filter((p) => p.stage >= dueStage(p, gap) || clearedByStepChange(p));
  if (!due.length) return;
  const rest = [];
  for (const a of due) {
    if (alreadyBuffed(a)) harvestAloe(a, true);
    else rest.push(a);
  }
  if (!rest.length) return;
  if (!BLASTBERRY_TECH) {
    for (const a of rest) harvestAloe(a, false);
    return;
  }
  const n = config.allowMutationDebt ? rest.length : Math.min(rest.length, inventory.get(JB));
  if (n < rest.length) {
    warnOnce("jbstock", `Cycle ${cycle}: not enough Magic Jellybeans for the Blastberry tech; some aloes are harvested without it.`);
  }
  const tech = rest.slice(0, n);
  if (tech.length) {
    withBlastberry(() => {
      for (const a of tech) {
        const r = a.row;
        const c = a.col;
        if (harvestAloe(a, true)) spendJellybean(r, c);
      }
    });
  }
  for (const a of rest.slice(n)) harvestAloe(a, false);
}

function harvestAloe(a, boosted) {
  const k = key(a.row, a.col);
  if (!a.harvest()) return false;
  tally.aloeHarvested++;
  if (boosted) tally.aloeBuffed++;
  if (leavingTo || !regrowStep() || !isSpot(k)) return true;
  if (REGROW_ALOE && !buffPhase) {
    if (!pending[k] && waiting[k] === undefined) waiting[k] = cycle;
  } else {
    emptied[k] = true;
  }
  return true;
}

/** A regrown aloe stands on its spot again: hand the cells back. */
function refreshSpots() {
  for (const k of keys(pending)) {
    const [r, c] = cellOf(k);
    const q = plot.at(r, c);
    if (q && q.kind === ALOE) {
      delete pending[k];
      tally.regrown++;
      if (!REMOVE_SCAFFOLD_AFTER_REGROW && !buffPhase) kept[k] = true;
    }
  }
  for (const k of keys(emptied)) {
    const [r, c] = cellOf(k);
    const q = plot.at(r, c);
    if (q && q.kind === ALOE) delete emptied[k];
  }
}

// ---- Regrow trigger ----
function scaffoldStanding(k) {
  return (aloeSource.scaffold[k] ?? []).every((s) => {
    const q = plot.at(s.row, s.col);
    return q && q.kind === s.kind && q.row === s.row && q.col === s.col;
  });
}

function startRegrow(k) {
  delete waiting[k];
  pending[k] = true;
  tally.regrowStarted++;
}

/** Waiting spots start regrowing once the trigger is met (all of them together). */
function startRegrows() {
  const ks = keys(waiting);
  if (!ks.length) return;
  const instant = REGROW_AFTER_ALOES === null && REGROW_INTERVAL === null;
  const oldest = Math.min(...ks.map((k) => waiting[k]));
  const byCount = REGROW_AFTER_ALOES !== null && ks.length >= Math.min(REGROW_AFTER_ALOES, aloeSource.spots.length);
  const byTime = REGROW_INTERVAL !== null && cycle - oldest >= REGROW_INTERVAL;
  if (instant || byCount || byTime) {
    tally.regrowBatches++;
    for (const k of ks) startRegrow(k);
    return;
  }
  if (JOIN_IF_SCAFFOLD_UP) {
    for (const k of ks) if (scaffoldStanding(k)) startRegrow(k);
  }
}

// ---- Jellybean buff ----
function dueJellybeans(gap) {
  return plot.spawns(JB).filter((p) => !p.dead && !p.fullyGrown && p.readyStage - p.stage <= gap && !buffed[p.id]);
}

function hasBuff(r, c, crop) {
  if (buffCells[key(r, c)] === crop) return true;
  const q = plot.at(r, c);
  return !!q && q.kind === crop && q.planted;
}

/** Cost of putting a buff crop on a cell; null = never (growing Jellybean, the other buff). */
function buffCost(r, c, crop) {
  const k = key(r, c);
  if (buffCells[k] && buffCells[k] !== crop) return null;
  const q = plot.at(r, c);
  if (isGrowingJellybean(q)) return null;
  // Never swap one buff crop for the other: a neighbour may be relying on it.
  if (q && q.planted && (q.kind === COCOA || q.kind === WART) && q.kind !== crop) return null;
  let cost;
  if (q && q.kind === crop && q.planted) cost = 0;
  else if (!q) cost = targetAt(r, c) === ALOE ? 8 : targetAt(r, c) ? 2 : 1;
  else if (q.dead) cost = 2;
  else if (q.kind === ALOE) cost = 50; // only if nothing else is next to it
  else if (q.spawned) cost = 3;
  else if (q.planted) cost = 4;
  else if (q.kind === PB) cost = 9;
  else cost = 6; // a placed item (Jellybean...)
  // Prefer cells that also touch other Jellybeans still to be buffed.
  const others = orth(r, c).filter(([a, b]) => {
    const p = plot.at(a, b);
    return isGrowingJellybean(p) && !p.fullyGrown && !buffed[p.id];
  }).length;
  return cost - 1.5 * Math.max(0, others - 1);
}

function buffJellybean(j) {
  for (const crop of [COCOA, WART]) {
    const cells = orth(j.row, j.col);
    if (cells.some(([r, c]) => hasBuff(r, c, crop))) continue;
    let best = null;
    for (const [r, c] of cells) {
      const cost = buffCost(r, c, crop);
      if (cost === null) continue;
      if (!best || cost < best.cost) best = { r, c, cost };
    }
    if (!best) {
      warnOnce(`buff${j.id}`, `Cycle ${cycle}: no free cell next to the Jellybean at (${j.row}, ${j.col}) for ${crop}.`);
      continue;
    }
    buffCells[key(best.r, best.c)] = crop;
  }
  buffed[j.id] = true;
  tally.jellybeansBuffed++;
}

// ---- Layout: the step's own layout plus regrow spots, scaffold and buffs ----
function buildLayout() {
  const entries = [];
  const at = {};
  function remove(i) {
    const e = entries[i];
    for (const k of footprint(e.row, e.col, e.size)) if (at[k] === i) delete at[k];
    entries[i] = null;
  }
  function add(e) {
    for (const k of footprint(e.row, e.col, e.size)) if (at[k] !== undefined && entries[at[k]]) remove(at[k]);
    entries.push(e);
    for (const k of footprint(e.row, e.col, e.size)) at[k] = entries.length - 1;
  }
  for (const p of base.plants) add({ plant: true, kind: p.kind, row: p.row, col: p.col, size: p.size });
  for (const t of base.targets) add({ plant: false, kind: t.mutation, row: t.row, col: t.col, size: t.size });
  for (const k of [...keys(waiting), ...keys(pending), ...keys(emptied)]) {
    const [r, c] = cellOf(k);
    add({ plant: false, kind: ALOE, row: r, col: c, size: 1 });
  }
  for (const k of [...keys(pending), ...keys(kept)]) {
    for (const s of aloeSource.scaffold[k] ?? []) {
      const e = at[key(s.row, s.col)];
      const same = e !== undefined && entries[e] && entries[e].plant && entries[e].kind === s.kind && entries[e].row === s.row && entries[e].col === s.col;
      if (!same) add({ plant: true, kind: s.kind, row: s.row, col: s.col, size: s.size });
    }
  }
  for (const k of keys(buffCells)) {
    const [r, c] = cellOf(k);
    add({ plant: true, kind: buffCells[k], row: r, col: c, size: 1 });
  }
  const live = entries.filter((e) => e);
  return {
    plants: live.filter((e) => e.plant).map((e) => ({ kind: e.kind, row: e.row, col: e.col, size: e.size })),
    targets: live.filter((e) => !e.plant).map((e) => ({ mutation: e.kind, row: e.row, col: e.col })),
  };
}

function applyLayout() {
  const changed = keys(waiting).length + keys(pending).length + keys(emptied).length + keys(kept).length + keys(buffCells).length > 0;
  if (!changed) {
    if (appliedKey !== null) {
      plot.resetLayout();
      appliedKey = null;
    }
    return;
  }
  const layout = buildLayout();
  const k = JSON.stringify(layout);
  if (k === appliedKey) return;
  plot.setLayout(layout);
  appliedKey = k;
}

// ---- Hooks ----
function onStart() {
  capture();
}

function onStepChange(e) {
  resetStep();
  capture();
}

function onSession() {
  trackGap();
  if (!base) capture();
  const gap = predictGap();

  // This script decides when aloes are harvested (so each gets the Blastberry tech).
  for (const p of plot.spawns(ALOE)) if (!p.protected) p.protect();
  // Harvest everything else first (as the built-in would), so we know if the step ends now.
  plot.runPhase("harvest");
  const to = plot.pending ?? plot.exitDue();
  leavingTo = to && to !== plot.step.id ? to : null;

  // Jellybeans that would be fully grown before the next session get their buff now.
  const due = BUFF_JELLYBEANS ? dueJellybeans(buffGap(gap)) : [];
  if (due.length && !buffPhase) {
    buffPhase = true;
    log(`Cycle ${cycle}: buffing Jellybeans (next session expected in ${gap} cycle${gap === 1 ? "" : "s"}); aloe regrow paused until the step ends.`);
    for (const k of [...keys(pending), ...keys(waiting)]) emptied[k] = true;
    pending = {};
    waiting = {};
    kept = {};
  }

  harvestAloes(gap);
  if (leavingTo) return; // the step changes this session: nothing to set up
  refreshSpots();
  startRegrows();
  for (const j of due) buffJellybean(j);
  applyLayout();
}

function afterSession() {
  // Learn each regrow spot's real respawn chance once its scaffold is complete.
  for (const k of keys(pending)) {
    if (qBySpot[k] !== undefined) continue;
    const [r, c] = cellOf(k);
    if (!plot.isEmpty(r, c)) continue;
    if (!scaffoldStanding(k)) continue;
    const hit = plot.spawnChances(r, c).find((x) => x.mutation === ALOE);
    if (hit && hit.chance > 0) qBySpot[k] = hit.chance;
  }
  metric("aloes harvested", tally.aloeHarvested);
  metric("aloes harvested with +30% and immunity", tally.aloeBuffed);
  metric("Magic Jellybeans spent on the Blastberry tech", tally.jellybeansSpent);
  metric("aloe regrow batches", tally.regrowBatches);
  metric("aloe regrows started", tally.regrowStarted);
  metric("aloes regrown", tally.regrown);
  metric("Jellybeans buffed", tally.jellybeansBuffed);
}
